  "卸载识谱引擎？之后图片 / PDF 识谱会退回内置引擎（离线可用，但变化音与节奏精度低）。": "認識エンジンをアンインストールしますか？画像／PDF の認識は内蔵エンジンに戻ります（オフラインで動作しますが、変化記号とリズムの精度は下がります）。",
  "请先转换出一份 MIDI": "先に MIDI へ変換してください",
  "这次没留下页图：请用图片或 PDF 转换后再校对": "今回はページ画像が残りませんでした：画像か PDF で変換してから照合してください",
