  "控件与间距紧凑度：紧凑 / 舒适 / 宽松": "コントロールと余白の密度：コンパクト／標準／ゆったり",
  "卡片与列表留白更多，长时间看谱不累": "カードやリストの余白が広がり、長時間の作業でも目が疲れにくくなります",
  "界面缩放": "画面の拡大率",
  "全局放大或缩小整个界面（0.9 ~ 1.3）：连画布一起缩放，不会糊也不会重叠": "画面全体を拡大／縮小します（0.9〜1.3）。キャンバスも一緒に拡大され、ぼやけたり重なったりしません",
