  "技法切换时发 Program Change（音色号 0-127）": "切り替え時にプログラムチェンジを送信（0〜127）",
  "技法切换时发一条 CC：控制器号": "切り替え時に CC を 1 つ送信：コントローラ番号",
  "CC 的值（0-127）": "CC の値（0〜127）",
  "力度系数：这次切换到下次切换之间的音符速度乘它（0.1~2）": "ベロシティ係数：この切り替えから次まで のノートに掛けます（0.1〜2）",
