  "频域底图：辅音与元音的差别在时域里看不出来，频域一眼能分": "スペクトログラム：子音と母音の違いは時間波形では分かりませんが、周波数領域では一目で分かります",
  "打开别名表：改原音设定 / 逐条试听（写回前自动备份 oto.ini.bak）": "別名テーブルを開く：原音設定の編集と1件ずつの試聴（保存前に oto.ini.bak を作成）",
