  "左侧就是工程的全部轨道。每轨自带引擎（UTAU / DiffSinger）、歌手与语言 —— 引擎在轨道上选，不是页面级切换。": "左側がプロジェクトの全トラックです。各トラックがエンジン（UTAU / DiffSinger）・歌手・言語を持ちます。",
  "从 MIDI 拿到旋律：多轨时会让您挑一条，音符落进当前声部轨（歌词留空，接着填）。": "MIDI から旋律を取得。複数トラックなら 1 つ選び、音符は現在の声部トラックに入ります（歌詞は空のまま）。",
  "导入音频（伴奏）": "音声を読み込む（伴奏）",
  "伴奏作为一条独立的音频轨加进来，与声部轨并列 —— 编辑时能听着伴奏对齐歌词，导出时混入。": "伴奏は独立した音声トラックとして声部トラックと並びます。編集時は聴きながら歌詞を合わせ、書き出し時に混ぜます。",
  "渲染本轨": "このトラックをレンダリング",
  "一个按钮，按该轨引擎自动分派（UTAU 走音源拼接，DiffSinger 走 AI 声学模型）。": "ボタン 1 つ。トラックのエンジンに応じて自動で振り分けます（UTAU は音源接続、DiffSinger は AI 音響モデル）。",
  "同时播放": "同時再生",
  "伴奏与渲染结果共用一个时钟同时起播（采样级同步），可以直接听对不齐的地方。": "伴奏とレンダリング結果を同じクロックで同時に再生（サンプル単位で同期）。ズレを直接聴き取れます。",
  "轨道属性": "トラックのプロパティ",
  "引擎特有的参数收在这里：UTAU 的重采样器/波源工具，DiffSinger 的采样深度与步数。": "エンジン固有の設定はここに集約：UTAU のリサンプラー/波形ツール、DiffSinger のサンプリング深度とステップ数。",
  "声库（两类混排）": "声庫（2 種類を 1 つの一覧に）",
  "UTAU 声库与 DiffSinger 声库在同一张列表里，类型只作标签 —— 正在被轨道使用的会标注「使用中」。": "UTAU と DiffSinger の声庫を同じ一覧に表示。種類はタグのみで、使用中のものは「使用中」と表示されます。",
  "UTAU 声库制作": "UTAU 声庫の作成",
  "选一个音源文件自动切分成音节、批量标注 oto 参数，再导出 oto.ini 或压缩包。": "音源ファイルを選ぶと自動で音節に分割し、oto パラメータを一括注釈して oto.ini やアーカイブを書き出します。",
  "DiffSinger 推理组件": "DiffSinger 推論コンポーネント",
  "启用模块后才下载组件（未启用零占用）；GPU 加速也在这里一键安装。": "モジュールを有効にしてからコンポーネントをダウンロードします（無効時は容量ゼロ）。GPU 加速もここで導入できます。",
  /* ---- 歌声合成（统一编辑器）引导文案 ---- */
  "歌声合成：一个编辑器，两种引擎": "歌声合成：1 つのエディタ、2 つのエンジン",
  "引擎是「轨道」的属性，不是页面模式：同一条工程里 UTAU 轨与 DiffSinger 轨可以混排。": "エンジンは「トラック」の属性でページモードではありません。1 つのプロジェクトに UTAU と DiffSinger のトラックを混在できます。",
  "每轨左侧选歌手与语言；点「渲染本轨」会按该轨的引擎自动分派，不需要来回切页面。": "トラックごとに歌手と言語を選び、「このトラックをレンダリング」がそのトラックのエンジンに自動で振り分けます。",
  "声库（UTAU 的 oto 制作 / DiffSinger 的组件与声库）统一在侧边栏「声库」里做，编辑器只负责选歌手。": "声庫（UTAU の oto 作成 / DiffSinger のコンポーネントと声庫）はこのページの「声库」タブに集約。エディタ側は選択のみ。",
  "歌声合成": "歌声合成",
  "轨道级引擎 · 导入 · 统一渲染": "トラック単位のエンジン · 読み込み · 統合レンダリング",
