  '能播放，但进度条总长不准；换成 wav/mp3 再导一次即可。': '再生はできますが全体の長さが不正確な場合があります。wav/mp3 で再取り込みしてください。',
  '检查这个音频文件能否被系统播放器打开。': 'この音声ファイルがシステムのプレイヤーで開けるか確認してください。',
  '文件可能被占用或没有读取权限，换一个位置再试。': 'ファイルが使用中か読み取り権限がない可能性があります。別の場所で試してください。',
  '确认它是标准 MIDI（.mid）；损坏或纯音频文件解析不了。': '標準 MIDI（.mid）か確認してください。破損ファイルや音声のみのファイルは解析できません。',
  '先去左侧「新建轨」建一条声部轨，再导入 MIDI。': '左側の「新規トラック」でボーカルトラックを作成してから MIDI を取り込んでください。',
