  '先渲染一次，或导入一个伴奏；也可以点传输栏的「重新装载」。': '一度レンダリングするか伴奏を取り込んでください。トランスポートバーの「再読み込み」でも可。',
  '渲染出的音频装载失败；点传输栏的「重新装载」再试。': 'レンダリング音声の読み込みに失敗しました。トランスポートバーの「再読み込み」を押してください。',
