  '选中音符后右侧自动打开属性检查器，可精确调整音高、力度、起点与长度。': '音符を選択すると右側にプロパティインスペクタが表示され、ピッチ・ベロシティ・開始位置・長さを正確に調整できます。',
  '乐谱页面': '楽譜ページ',
  '自动根据音域切换高低音谱号，并使用 8va / 8vb / 15ma 避免加线“梯子”。': '音域に応じて高音部・低音部の譜表を自動切り替えし、8va / 8vb / 15ma を使って加線の「はしご」を回避します。',
  '符干方向按谱号中线规则优化，音符间距与连线排版更均匀。': '符幹の向きを譜表の中線ルールに基づいて最適化し、音符間隔と連符の配置をより均一にします。',
