  '最小化 / 关闭到托盘': '最小化 / 終了時にトレイへ',
  '最小化 / 关闭将隐藏到托盘后台播放': '最小化 / 終了でトレイに隠れ、バックグラウンドで再生を続けます',
  '将清除以下本地数据：n· 已下载的转录模型n· 已下载的音色（SF2）n· 资源中心安装的依赖（GPU 增强包等）n· 播放进度、书签与播放统计nn不会删除你的 MIDI 曲库、歌单与收藏。n清除后应用将自动重启。确定继续？': '以下のローカルデータを消去します：n・ダウンロード済みの転写モデルn・ダウンロード済みの音源（SF2）n・リソースセンターでインストールした依存関係（GPU 拡張パックなど）n・再生位置、ブックマーク、再生統計nnMIDI ライブラリ、プレイリスト、お気に入りは削除されません。n消去後、アプリは自動的に再起動します。続行しますか？',
  '清除中…': '消去中…',
  '用户数据已清除，应用即将重启…': 'ユーザーデータを消去しました。アプリを再起動します…',
  '清除失败：': '消去に失敗しました：',
  '当前环境不支持': 'この環境ではサポートされていません',
