  '自定义': 'カスタム',
  '低音增强': '低音ブースト',
  '节拍网格检测': 'ビートグリッド',
  '反馈': 'フィードバック',
  '遇到问题？先跑一次体检': '問題がありますか？まずチェックを',
  '体检会把系统、显卡与加速包、运行时依赖、模型资源和最近错误逐条查一遍并给出结论；报告已自动去掉用户名与机器名，可以直接粘贴到反馈里。': 'システム・GPU と高速化パッケージ・実行時依存・モデル・最近のエラーを項目ごとに検査し結論を出します。レポートはユーザー名とマシン名を除去済みなので、そのまま貼り付けられます。',
  '去 GitHub 反馈': 'GitHub で報告',
  '先看看已知问题': '既知の問題を確認',
  '点「去 GitHub 反馈」会先把体检报告复制到剪贴板，再打开一个预填好标题与正文的 issue 页面 —— 粘贴即可提交。': '「GitHub で報告」を押すと、まずチェック結果をクリップボードにコピーし、タイトルと本文を入力済みの issue ページを開きます。貼り付けて送信するだけです。',
  '计算精度': '計算精度',
  '实测在 10 分钟 / 120 块的长素材上，bf16 与 fp32 耗时相同（CPU 569s vs 569s、显卡 119s vs 119s），输出逐项一致。所以它不是一个提速档 —— 保留仅为降低显存/内存占用。默认 fp32': '10 分 / 120 チャンクの長い素材では、bf16 と fp32 の所要時間は同じでした（CPU 569s 対 569s、GPU 119s 対 119s）。出力は項目ごとに一致します。つまり高速化オプションではなく、VRAM / メモリ使用量を下げるためだけに残しています。既定は fp32。',
  'bf16（省显存，实测不更快）': 'bf16（VRAM 節約・実測では速くならない）',
  'fp32（默认，最稳）': 'fp32（既定・最も安全）',
  'bf16（纯 CPU 快约 43%）': 'bf16（CPU で約 43% 高速）',
  'fp16（更激进，未验证）': 'fp16（より積極的・未検証）',
  '遇到问题？': '問題がありますか？',
  '一键体检 · 反馈到 GitHub': 'ワンクリック診断 · GitHub へ報告',
  '反馈问题': '問題を報告',
  '已知问题': '既知の問題',
  '[体检反馈] 请把症状补在这里': '[チェック] 症状をここに記入',
  '（体检报告已复制到剪贴板，请粘贴到这里）': '（チェック結果をクリップボードにコピー済み。ここに貼り付けてください）',
  '调试工具 · 全局体检': 'デバッグツール · 総合チェック',
  '开始体检': 'チェック開始',
  '体检中…': 'チェック中…',
  '复制报告': 'レポートをコピー',
  '导出诊断包': '診断パッケージを書き出す',
  '看完整报告': '詳細レポートを表示',
  '看结论': '結論を表示',
  '体检会检查系统、显卡与加速包、运行时依赖、模型资源和最近错误，并逐条给出结论。报告已自动去掉用户名与机器名，可直接粘贴到反馈里。': 'システム・GPU と高速化パッケージ・実行時依存・モデル・最近のエラーを検査し、項目ごとに結論を出します。レポートはユーザー名とマシン名を除去済みなので、そのまま不具合報告に貼れます。',
  '当前环境不支持体检': 'この環境ではチェックを利用できません',
  '体检失败': 'チェックに失敗しました',
  '（未经实机验证）': '（実機未検証）',
  'Intel XPU 面向 Intel Arc 独显 / 部分核显（torch+xpu）。本包尚未在 Intel 显卡实机上验证过：安装后会自动在显卡上跑一次矩阵乘并与 CPU 结果对拍，通不过就判为不可用并自动改用 CPU，不会让转录中途出错。': 'Intel XPU は Intel Arc 搭載 GPU / 一部の内蔵 GPU 向け（torch+xpu）。本パッケージは Intel 実機で未検証です：インストール後に GPU 上で行列積を実行し CPU の結果と照合します。通らなければ使用不可と判定して自動的に CPU へ切り替えるため、文字起こしが途中で壊れることはありません。',
  '阈值 · 踏板 · 模型选项': 'しきい値 · ペダル · モデルオプション',
