  '短按方向键按步长跳；按住不放则按倍数播放（→ 快进播放，← 快退且不出声）。': '方向キーを短押しすると移動幅ぶん移動し、押し続けると倍速再生になります（→ は音ありの早送り、← は音を出さずに巻き戻し）。',
  '改完立刻生效，不用重启': '変更はすぐ反映されます（再起動不要）',
