  '静音判定阈值': '無音とみなすしきい値',
  '最高音高': '最高音高',
  '不限制': '制限なし',
  '超过就强制收尾，治长音频的僵尸音符（实测 100 分钟录播出现过 4320 秒的音）。调大＝少干预，调小＝更狠地剪长音；0 = 关': 'これを超える音を強制終了します。長い音源のゾンビノート対策（100 分の録画で 4320 秒の音が出た実例あり）。大きく＝介入少なめ、小さく＝長音を強く切る。0 = オフ',
  '采样温度': 'サンプリング温度',
  '调高＝更随机、更有可能跳出重复；默认 1.0 走贪婪解码，结果可复现': '高いほどランダムで繰り返しから抜けやすくなります。1.0 は貪欲法で再現可能',
  '引导系数': 'CFG 係数',
  '调高＝更贴近提示但更容易重复；默认 1.0 = 关闭引导': '高いほどプロンプトに忠実ですが繰り返しが増えます。1.0 = オフ',
  '束搜索宽度': 'ビーム幅',
  '同时保留多条候选再挑最好；越大越慢，默认 1 = 关闭': '複数の候補を並行して保持し最良を選びます。大きいほど遅く、1 = オフ',
  '下落速度': '落下速度',
  '视觉偏移(ms)': '表示オフセット(ms)',
  '左右手音区': '左右手＋音域',
  '跨块延音缝合': 'チャンク境界のサスティン縫合',
  '解码后把 5 秒分块边界两侧同音高、同音色的延音缝回一个长音：延音不断，而模型不再被强制拖着走 —— 从根上消除僵尸长音。关掉＝不缝合，边界处延音可能断（默认开）': 'デコード後に、5 秒のチャンク境界をまたいで同音高・同音色の音を 1 つの長音に縫い合わせます。サスティンは途切れず、モデルが古い音を無理に延ばすこともなくなります（ゾンビ長音を根本から解消）。オフ＝縫合しない（境界で音が切れる可能性、既定オン）',
  '跨块延音前置': 'プリリュード強制',
