  '将清除以下本地数据：\n· 已下载的转录模型\n· 已下载的音色（SF2）\n· 资源中心安装的依赖（GPU 增强包等）\n· 播放进度、书签与播放统计\n\n不会删除你的 MIDI 曲库、歌单与收藏。\n清除后应用将自动重启。确定继续？': '次のローカルデータを消去します：\n・ダウンロード済みの転写モデル\n・ダウンロード済みの音色（SF2）\n・リソースセンターでインストールした依存（GPU 拡張パック等）\n・再生履歴、ブックマーク、再生統計\n\nMIDI ライブラリ、プレイリスト、お気に入りは削除されません。\n消去後、アプリは自動的に再起動します。続行しますか？',
