  "选择/画笔/橡皮三种工具；拖拽移动音符、边缘拉伸改时值、Alt 拖拽调力度；支持吸附、音阶吸附、撤销/重做。": "選択／ペン／消しゴムの3つのツール。ドラッグで音符を移動、端をドラッグで長さ変更、Alt ドラッグでベロシティ調整。スナップ、スケールスナップ、元に戻す／やり直しに対応。",
  "CC 自动化": "CC オートメーション",
  "展开 CC 泳道后选择 CC1/7/10/11/64；支持手绘、直线、曲线三种绘制；点击/拖动直接写 CC 数据。": "CC レーンを展開して CC1/7/10/11/64 を選択。フリーハンド、直線、カーブの3種類で描画でき、クリック／ドラッグで CC データを直接書き込めます。",
  "C-2~C0 区域橙色高亮；支持自定义技法名称，并提供 Spitfire/VSL/EastWest 预设模板。": "C-2～C0 の範囲がオレンジで強調表示され、技法名のカスタマイズや Spitfire/VSL/EastWest のプリセットに対応。",
  "按“目标→条件→操作”批量修改音符：力度、时值、音高、删除、量化、移调。": "「対象→条件→操作」で音符を一括変更：ベロシティ、長さ、音高、削除、クオンタイズ、移調。",
  "以表格精确编辑每个音符的起点/终点/音高/力度；支持添加、删除、排序。": "表形式で各音符の開始／終了／音高／ベロシティを正確に編集。追加、削除、並べ替えに対応。",
  "宏系统": "マクロシステム",
  "内置清理/移调/力度标准化宏；支持自定义命令宏。": "クリーン／移調／ベロシティ標準化のマクロを内蔵。カスタムコマンドマクロにも対応。",
  "按 1/4、1/8、1/16、1/32 量化；支持 Funk/Jazz/Rock/Latin/自定义 Groove；可提取选中音符的 Groove。": "1/4、1/8、1/16、1/32 でクオンタイズ。Funk/Jazz/Rock/Latin／カスタム Groove に対応し、選択した音符から Groove を抽出できます。",
  "打击乐专用网格视图，点击添加/删除鼓点，支持鼓轨切换与清除。": "打楽器専用のグリッド表示。クリックでドラムヒットを追加／削除し、ドラムトラックの切り替えと消去に対応。",
  "基于当前旋律/和弦自动生成 贝斯 + 分解和弦 + 铺底 3 轨（可撤销）。": "現在のメロディ／コードからベース＋分散和音＋パッドの3トラックを自動生成（元に戻せます）。",
  "音频对齐": "音声の位置合わせ",
  "载入原音频后在卷帘底部显示波形；「吸附起音」把音符吸附到最近的波形起音（±80ms）；「试听」同步播放原音频检查对齐效果。": "元の音声を読み込むとロール下部に波形を表示。「オンセットにスナップ」で音符を最も近い波形オンセット（±80ms）に合わせ、「試聴」で元音声を同期再生して位置合わせを確認できます。",
