  "选择/画笔/橡皮/静音四种工具；拖拽移动音符、边缘拉伸改时值、Alt 拖拽调力度；支持吸附、音阶吸附、撤销/重做；可设置新音符默认力度与着色方案（轨道/音高/力度/选中）。": "選択/ペン/消しゴム/ミュートの4つのツール。ドラッグでノートを移動、ノートの端をドラッグで長さを変更、Alt+ドラッグでベロシティを調整。スナップ、スケールスナップ、元に戻す/やり直しに対応。新規ノートのデフォルトのベロシティと配色（トラック/音高/ベロシティ/選択）を設定できます。",
  "C-2~C0 区域橙色高亮；技法名来自演奏法库（内置 Spitfire/VSL/EastWest，可另存为自定义库并绑定到轨道）。": "C-2~C0 の範囲をオレンジでハイライト。奏法名は奏法ライブラリから取得します（Spitfire/VSL/EastWest を内蔵、カスタムライブラリとして保存しトラックにバインドできます）。",
