  '已启用（点击禁用）': '有効（クリックで無効化）',
  'DiffSinger 歌声合成仅桌面版可用（需要 Python 引擎与 ONNX 推理组件）。': 'DiffSinger の歌声合成はデスクトップ版のみ利用できます（Python エンジンと ONNX 推論コンポーネントが必要です）。',
  'DiffSinger 是可选模块：未启用时不下载、不安装任何组件，与应用其他功能完全隔离。启用后可安装推理组件并导入声库。': 'DiffSinger はオプションのモジュールです。無効な間は一切ダウンロード・インストールせず、アプリの他の機能から完全に分離されます。有効化すると推論コンポーネントのインストールと音源のインポートが可能になります。',
  '模块已启用。点击「安装组件」下载推理依赖与通用声码器后即可开始调教。': 'モジュールが有効になりました。「コンポーネントをインストール」をクリックして推論依存関係と汎用ボコーダーをダウンロードすれば調声を始められます。',
  '禁用保留已下载组件；重新启用即可继续使用。': '無効化してもダウンロード済みコンポーネントは保持されます。再度有効化すればそのまま使えます。',
  '推理组件': '推論コンポーネント',
