  '支持 OpenUTAU 格式的 DiffSinger 声库（含 dsconfig.yaml 的 zip）；.oudep 依赖包会安装为通用声码器。': 'OpenUTAU 形式の DiffSinger 音源（dsconfig.yaml を含む zip）に対応。.oudep 依存パッケージは汎用ボコーダーとしてインストールされます。',
