  '串行渲染每一条声部轨（结果按轨保存，渲第二条不会顶掉第一条），渲完一起播放。一条几十秒，进度会显示到第几条。': 'ボーカルトラックを 1 本ずつ順番にレンダリングします（結果はトラックごとに保持されるため、次をレンダリングしても前の結果は消えません）。1 本に数十秒かかり、進捗に何本目か表示されます。',
  '按空格直接播：没渲染或已过期的声部轨会自动补渲染再一起响（播放即全轨）。伴奏与所有声部轨共用一个时钟采样级同步，每条轨可单独静音。': 'Space で直接再生：未レンダリング・古くなったボーカルトラックは自動で再レンダリングされて一緒に鳴ります（再生時フルレンダリング）。伴奏とすべてのボーカルトラックがサンプル精度の同一クロックで同期し、トラックごとのミュートも可能。',
  '工程文件': 'プロジェクトファイル',
  '.fufumidi 是自包含工程包：伴奏等外部文件一起打进包里，所以换台机器打开不会断链（包内不存本机绝对路径）。': '.fufumidi は自己完結型のパッケージです。伴奏などの外部ファイルもまとめて入るため、別のマシンで開いてもリンク切れになりません（ローカルの絶対パスは保存しません）。',

