  /* ガイド：トラックプロパティ（3 ブロック） */
  '三块：参数（UTAU 的重采样器/波源工具，DiffSinger 的采样深度与步数）、效果链（本轨独享，从上到下就是信号流）、自动化子轨（PIT 与 DYN/BRE/GEN 改了要重渲，VOL/PAN 播放时实时生效）。': '3 つのセクション：パラメータ（UTAU のリサンプラー/波形ツール、DiffSinger のサンプリング深度とステップ数）、エフェクトチェーン（トラック専用。上から下が信号の流れ）、オートメーション（PIT と DYN/BRE/GEN は再レンダリングが必要、VOL/PAN は再生時にリアルタイム反映）。',

  /* ---- 調教（エディタ + 音源を 1 ページに統合） ---- */
  '调教': '調教',
  '歌声合成 · 声库 · 渲染': '歌声合成 · 音源 · レンダリング',
  '编辑器': 'エディタ',
  '选歌手 · 画音符 · 渲染': '歌手選択 · ノート入力 · レンダリング',
  '同一页：左边做声库、右边调教渲染': '同じページ：左で音源管理、右で調教とレンダリング',
  '声库管理': '音源管理',
  '调教：一个页面，编辑器 + 声库': '調教：1 つのページにエディタ + 音源',
  'DiffSinger 轨还有谱面编辑：卷帘下方有音素条带与音高车道；顶部编排时间线管理整条工程的渲染片段。支持直接打开 OpenUTAU 的 .ustx / .ust 工程。': 'DiffSinger トラックには譜面編集もあります。ロールの下に音素ストリップとピッチレーン、上部にプロジェクト全体のレンダリングクリップを管理するアレンジタイムライン。OpenUTAU の .ustx / .ust プロジェクトを直接開けます。',
  '编辑器 + 声库 · 轨道级引擎 · 统一渲染': 'エディタ + 音源 · トラック単位のエンジン · 統合レンダリング',
  '两个页签': '2 つのタブ',
  '「调教」把编辑器与声库合成了一页：编辑器选歌手 / 画音符 / 渲染，声库做 / 装 / 管声库与推理组件。点这个页签随时来回切。': '「調教」はエディタと音源ページを 1 つに統合しました。エディタで歌手選択・ノート入力・レンダリング、音源タブで音源と推論コンポーネントの作成・導入・管理を行います。タブでいつでも切り替えられます。',
  '切到「声库」页签：UTAU 声库与 DiffSinger 声库在同一张列表里，类型只作标签 —— 正在被轨道使用的会标注「使用中」。': '「声库」タブに切り替えると、UTAU と DiffSinger の音源が同じ一覧に並びます。種類はタグのみで、使用中のものは「使用中」と表示されます。',
  '启用模块后才下载组件（未启用零占用）；GPU 加速也在这里一键安装。做完切回「编辑器」页签继续调教。': 'モジュールを有効にしてからコンポーネントをダウンロードします（無効時は容量ゼロ）。GPU 加速もここで導入できます。終わったら「エディタ」タブに戻って調教を続けてください。',

