  '翻唱': 'カバー',
  '一首歌 → 分离人声 → 用导入的模型换音色 → 混音成成品': '1曲 → ボーカル分離 → 取り込んだモデルで音色変換 → ミックスして完成',
  '一首歌 → 分离 → 变声 → 混音 → 成品。音色来自你导入的 RVC 模型（应用不内置、不代下载）。': '1曲 → 分離 → 音色変換 → ミックス → 完成。音色は取り込んだ RVC モデル由来です（アプリは同梱も代理ダウンロードもしません）。',
