  '有 LRC 时每句都能对上；没有歌词就整首用「啦」哼唱': 'LRC があれば各行が合います。歌詞がなければ全曲「ラー」でハミングします',
  '还没有 GPT-SoVITS 音色，去「资源中心」下载': 'GPT-SoVITS 音色がまだありません。「リソースセンター」でダウンロードしてください',
  '还没有 DiffSinger 声库，去「调教 → 声库」安装': 'DiffSinger 音源がまだありません。「調教 → 音源」でインストールしてください',
