  '请使用桌面版': 'デスクトップ版 FuFumidi をご利用ください',
  '请使用桌面版 FuFumidi': 'デスクトップ版 FuFumidi をご利用ください',
  '成品': '完成音源',
  '干声': 'ドライボーカル',
  '打开文件夹': 'フォルダを開く',
  '音符': '音符',
  '配平': 'レベル調整',
  /* ---- 新手引导（5.0.0 更新）---- */
  '打开工程时选 .ustx / .ust 也可以：轨道、音符、音高曲线完整导入，语言还会按歌词自动判断；编辑完也能导出回 .ustx 交给 OpenUtau 继续用。': '.ustx / .ust ファイルも開けます。トラック・音符・ピッチカーブを完全に取り込み、歌詞から言語を自動判定。編集後は .ustx に書き出して OpenUtau に戻せます。',
  'OpenUTAU 工程互通': 'OpenUTAU プロジェクト相互運用',
  '顶部的时间线把整条工程铺开：每条轨一行，一段段「part 块」就是已渲染的片段。双击聚焦到编辑器对应位置，拖动可整段移动。': '上部のタイムラインにはプロジェクト全体が並びます。1 行 = 1 トラック、各「パート」ブロックがレンダリング済みクリップ。ダブルクリックでその位置にフォーカス、ドラッグでまとめて移動できます。',
  '编排时间线': 'アレンジタイムライン',
  '谱面编辑：音素与音高': '譜面編集：音素とピッチ',
  '卷帘下方就是音素条带与音高车道：音素可以单独点选改表达（辅音轻、元音亮），音高车道用多种工具在 ±200 音分内画偏移，随工程保存并纳入撤销。': 'ロールの下が音素ストリップとピッチレーンです。音素は個別にクリックして表現を調整（子音を弱く・母音を明るく）し、ピッチレーンは複数のツールで ±200 セントの範囲に描けます。プロジェクトに保存され、元に戻す操作にも対応。',
  '翻唱工作流': 'カバーワークフロー',
  '分离 → 扒谱 → 合成 → 混音，一条龙做翻唱': '分離 → 採譜 → 合成 → ミックス、カバー制作をワンストップで',
  '选一首歌': '曲を選ぶ',
  '翻唱走「分离 → 扒谱 → 合成 → 混音」四步：选入一首完整歌曲，应用自动把人声与伴奏分开，把人声转成旋律，再用你选的音色唱出来。': 'カバーは「分離 → 採譜 → 合成 → ミックス」の 4 ステップ。完全な曲を選ぶと、アプリがボーカルと伴奏を分離し、ボーカルを旋律化して、選んだ音声で歌わせます。',
  '如果之前在「音频处理」里分离过这首歌，人声与伴奏会自动带过来，直接跳过分离这一步（省时间）。': '「音声処理」でこの曲を分離済みなら、ボーカルと伴奏が自動で引き継がれ、分離ステップを省略できます（時間の節約）。',
  '分离 → 变声 → 混音，一条龙做翻唱': '分離 → ボイスチェンジ → ミックス、ワンストップでカバー',
  '翻唱走「分离 → 变声 → 混音」三步：选入一首完整歌曲，应用自动把人声与伴奏分开，用你导入的 RVC 模型把原唱换成另一个音色，再和伴奏混成成品。旋律、节奏、咬字都来自原唱，不需要歌词。': 'カバーは「分離 → ボイスチェンジ → ミックス」の3ステップです。曲を1曲選ぶと、アプリがボーカルと伴奏を分離し、取り込んだRVCモデルで元の声を別の音色に差し替え、伴奏とミックスして完成させます。メロディ・リズム・発音はすべて原曲由来で、歌詞は不要です。',
  '选翻唱模型': 'カバーモデルを選ぶ',
  '去模型管理': 'モデル管理へ',
  '不分离 —— 变声整曲': '分離しない —— 曲全体をボイスチェンジ',
  '加速未就绪，将用 CPU': 'GPU未準備完了、CPUを使用します',
  '分离模型需要先在「模型管理」里下载；不选就整曲直接变声': '分離モデルは先に「モデル管理」でダウンロードする必要があります。未選択の場合は曲全体をボイスチェンジします。',
  '还没有导入 RVC 模型：可直接在这里导入，也可以去「模型管理 → RVC 模型」里管理': 'RVCモデルが未インポートです：ここで直接インポートするか、「モデル管理 → RVCモデル」で管理できます。',
  '音色来自你导入的 RVC（RVC）模型：应用不内置也不代下载，去「模型管理 → 翻唱模型」导入社区权重即可（导入时可逐项探测版本 / f0 / 采样率，探测值只是候选，以权重真实读数为准）。': '音色は取り込んだRVC（RVC）モデルから来ます。アプリには同梱せず、自動ダウンロードもしません。「モデル管理 → カバーモデル」からコミュニティの重みをインポートしてください（インポート時にバージョン / f0 / サンプリングレートを項目ごとに検出しますが、検出値は候補に過ぎず、重みの実測値が優先されます）。',
  '选好输出目录后点「开始翻唱」：长曲自动按低能量点切块推理再混音，支持断点续跑（中断后可继续，或勾选「不复用上次结果」全部重算）。': '出力フォルダを選んで「カバー開始」を押してください。長い曲は低エネルギー地点で自動的にブロック分割して推論し、その後ミックスされます。中断後の再開に対応しています（「前回の結果を使わない」にチェックで全計算のやり直しも可能です）。',
  '选音色类型': '音声タイプを選ぶ',
  'DiffSinger 音色来自声库工坊，即选即用；GPT-SoVITS 音色需要本机运行时（v2pro）与参考音频。两种都能在本地完成合成。': 'DiffSinger 音声はボイスバンク工房から選んですぐ使えます。GPT-SoVITS 音声はローカルランタイム（v2pro）と参照音声が必要です。どちらもローカルで合成できます。',
  '歌词由扒谱自动生成，也可以手动修改 —— 合成时会按歌词逐字唱。': '歌詞は採譜で自動生成され、手動でも編集できます。合成時は歌詞の一字一句に沿って歌います。',
  '选好输出目录后点「开始翻唱」：按段合成再自动混音，支持断点续跑（中断后可继续，或勾选「不复用上次结果」全部重算）。': '出力フォルダーを選んで「カバー開始」をクリック。セグメントごとに合成して自動ミックスし、中断からの再開に対応しています（「前回の結果を再利用しない」にチェックすると全て再計算）。',

