  "严重度": "重大度",
  "填好点「上传到反馈仓库」即可。体检报告会自动附上（已去掉用户名与机器名）；诊断包含设置与最近日志，默认不带，需要时自己勾。": "入力して「フィードバックリポジトリへアップロード」を押すだけです。チェック結果は自動で添付されます（ユーザー名とマシン名は除去済み）。診断パックにはログと設定が含まれるため既定ではオフです。",
  "打开资源中心": "リソースセンターを開く",
  "去资源中心安装": "リソースセンターでインストール",
  "这四样都要在资源中心单独安装（不随安装包分发，装在数据根的 omr 目录）。没装也能用内置识谱，只是精度低一档、读不出乐器名与速度记号。": "この 4 つはリソースセンターから個別にインストールします（同梱されず、データルートの omr フォルダーに入ります）。未導入でも内蔵認識は使えますが、精度が一段下がり、楽器名や速度記号は読めません。",
  "读乐器名 / 速度记号 / 和弦名": "楽器名・速度記号・コード名を読み取る",
  "谱表量不出来或行距 < 5px 时先神经放大": "譜表が測れない、または行間が 5px 未満のときにニューラル拡大",
  "超分辨率（低清扫描）": "超解像（低解像度スキャン）",
  "扫描件 / 拍照首选：神经网络整页识谱": "スキャン・撮影に最適：ニューラルによるページ全体の認識",
  "印刷谱首选：小节结构与变化音更准": "印刷譜に最適：小節構造と変化記号がより正確",
  "homr（AI 识谱）": "homr（AI 認識）",
  "Audiveris 增强引擎": "Audiveris エンジン",
  "齐备": "すべて導入済み",
  " 项": " 件",
  "缺 ": "不足 ",
  "识谱组件": "認識コンポーネント",
  "给低清扫描件 / 拍照件做神经放大（waifu2x，走显卡 Vulkan）。Audiveris 官方给低分辨率谱的建议就是这条路。实测一张 0.4 倍的总谱页（谱表都量不出来）：不超分 0 个音符，超分后 253 个；「自动」只在谱表量不出来或行距低于 5px 时才动手 —— 清晰印刷谱与矢量 PDF 渲染的低清页一律不碰（实测给清晰页超分反而把一致性从 1.00 拉到 0.82）。": "低解像度のスキャン・スマホ撮影向けのニューラル拡大（waifu2x／GPU の Vulkan を使用）。Audiveris 公式が低解像度譜に勧めている方法です。実測：0.4 倍に縮めた総譜ページ（譜表すら検出できない）で、未使用 0 音 → 使用 253 音。「自動」は譜表が測れないか行間が 5px 未満のときだけ動きます —— きれいな印刷譜とベクター PDF 由来の低解像度ページには一切触れません（実測：きれいなページに超解像をかけると一致度が 1.00 から 0.82 に下がります）。",
  "安装超分辨率": "超解像をインストール",
  "超分辨率组件已安装": "超解像コンポーネントをインストールしました",
  "卸载超分辨率组件？之后低清扫描件（行距 < 11px）会退回普通插值放大，识别率明显下降。": "超解像コンポーネントを削除しますか？低解像度スキャン（行間 11px 未満）は通常の補間拡大に戻り、認識率が大きく下がります。",
  "已卸载超分辨率组件": "超解像コンポーネントを削除しました",
