  "单乐器钢琴谱：两行大谱表、页宽通常够 —— 用「自动放大 + 不加粗」一次就能用。": "単一楽器のピアノ譜：2 段の大譜表で解像度は通常十分 ——「自動拡大 + 太らせない」で大抵一発で使えます。",
  "管弦乐总谱：一页几十行谱表，识别失败的那几页会逐页列在结果里（不再静默少页）。": "オーケストラ総譜：1 ページに数十段 —— 認識に失敗したページは結果に 1 ページずつ表示されます（黙って欠落しません）。",
  "扫描件 / 手机拍照：打开「加粗谱线」并放大 —— 谱线一断，整页都会被判为无效。": "スキャン / スマホ撮影：「譜線を太らせる」をオンにして拡大 —— 譜線が途切れるとページ全体が無効と判定されます。",
  "MusicXML / MIDI：不经过识谱，直接精确转换；右栏参数对它们不生效。": "MusicXML / MIDI：認識を通さず正確に変換します。右側のパラメータは適用されません。",
