  "（谱面记号没读准，可在右栏手填）": "（譜面の記号を読み取れませんでした。右パネルで入力できます）",
  "扫描件 / 手机拍照的首选：神经网络整页识谱。代码是 AGPL-3.0、权重含非商用数据，所以不随安装包分发，需要在这里自己装（约 300 MB，装在独立环境里，不影响其它功能）。": "スキャン・スマホ撮影の本命：ニューラルによるページ全体の楽譜認識。コードは AGPL-3.0、重みに非商用データを含むため同梱できません。ここから自分でインストールしてください（約 300 MB、独立した環境に入るので他の機能に影響しません）。",
