  "没装识谱增强引擎（Audiveris），已用内置识谱；可在「资源中心 → 识谱引擎」安装后重试。": "拡張楽譜認識エンジン（Audiveris）が未インストールのため内蔵認識を使用しました。「リソース → 楽譜認識エンジン」からインストールして再試行してください。",
