  "分辨率不足：把「放大倍数」调到 4×，或换更高清的图。": "解像度不足：「拡大倍率」を 4× にするか、より鮮明な画像を使ってください。",
  "内存不足（已自动降档重试）：仍失败就把放大倍数调小一档。": "メモリ不足（低倍率での再試行は実行済み）。それでも失敗する場合は拡大倍率を一段下げてください。",
  "识别超时：这一页太密，建议拆页或把放大倍数调小。": "認識がタイムアウトしました。ページが密なので分割するか拡大倍率を下げてください。",
  "没找到五线谱：确认这一页是谱面，而不是封面或纯文字页。": "五線譜が見つかりません。表紙や文字だけのページでないか確認してください。",
  "符杠厚度估算不可靠：常见于符杠很少的页，可试「加粗谱线」。": "符尾（ビーム）の太さを推定できません（ビームが少ないページでよく発生）。「譜線を太らせる」を試してください。",
  "识别完成但导出失败：多为分辨率或内存问题，已自动降档重试过。": "認識は完了しましたが書き出しに失敗しました。多くは解像度かメモリの問題で、低倍率での再試行は実行済みです。",
  "资源中心": "リソースセンター",
  "没装 OCR 语言包：乐器名、速度记号、和弦名都读不出来（声部只能叫「声部 N」）。可在「资源中心 → 识谱引擎」装英语包，约 23 MB。": "OCR 言語パックが未導入です：楽器名・テンポ記号・コードネームを読み取れません（パート名は「声部 N」のまま）。「リソースセンター → 譜面認識エンジン」から英語パック（約 23 MB）を入れてください。",
