"Audiveris 5.5 起不预装任何 OCR 语言；没有语言时它的文字识别步骤整段跳过 —— 速度记号、乐器名、和弦名都读不到。装上对应语言（完整版，每个约 23 MB）即可。": "Audiveris 5.5 以降は OCR 言語データを同梱していません。言語がないと文字認識ステップが丸ごと省略され、テンポ記号・楽器名・コードネームが一切取れません。必要な言語（各約 23 MB）を入れてください。",
